/* From Uiverse.io by kamehame-ha - Tags: input, clean, bash, cmd, linux */
.__UIV_SCOPE__ .input-container {
  display: flex;
  align-items: center;
  background-color: #0F172A;
  padding: 10px 15px;
  gap: 5px;
  border-radius: 20px;
}

.__UIV_SCOPE__ .input-container .bash-text {
  font-size: .8rem;
  color: white;
}

.__UIV_SCOPE__ .input-container .bash-text .user {
  color: #E879F9;
}

.__UIV_SCOPE__ .input-container .bash-text .vm {
  color: #2DD4BF;
}

.__UIV_SCOPE__ .input-container .bash-text .char {
  color: #A78BFA;
}

.__UIV_SCOPE__ .input-container input[type=text].input {
  background-color: transparent;
  border: none;
  outline: none;
  color: white;
}
